const e={back:"Back",continue:"Continue",step_of:"{current} of {total}",welcome:{title:"Welcome",lede:"First a short look at what {name} is and how it works. Then we set it up right here in the app: an API key, a subscription for your agents and your wake word.",language:"Language",lang_en:"English",lang_de:"Deutsch",lang_es:"Español",start:"Let's start"},how:{title:"How {name} works",lede:"One assistant you talk to. Behind it: a brain, tools, a team of agents and a memory.",next:"Next",prev:"Back",skip:"Skip the explanation",finish:"Got it, let's set it up",chapter_of:"{current} / {total}",chapters_label:"Chapters",map_label:"How the parts of your assistant connect",journey_pick:"Pick an example request",journey_replay:"Play again",nodes:{center:"{name}",you:"You",you_sub:"Voice, chat, phone",brain:"Brain",brain_sub:"The AI model",tools:"Tools",tools_sub:"Computer, apps, web",agents:"Agents",agents_sub:"Team for big jobs",memory:"Memory",memory_sub:"Wiki and profile",results:"Results",results_sub:"Answers and files",safety:"Safety check"},chapters:{intro:{title:"One assistant for everything",say:"Hi, I'm Gigi! {name} is not just another chatbot. It is ONE assistant that works on your computer for you. You only ever talk to {name}: it decides what needs doing and who does it.",p1:"No switching between apps or AI tools. You say what you want, once.",p2:"{name} thinks, uses your computer and your apps, and hands big jobs to helper agents.",p3:"Everything comes back to you in one place: spoken aloud, in the chat, or as a finished file."},you:{title:"Talk to it any way you like",say:"Speak, type or write from your phone. Every way leads to the same {name}, with the same memory.",p1:"Voice: say your wake word or press the Call shortcut, then just talk. {name} answers aloud.",p2:"Chat: type in the app. Every conversation is saved under Recent chats.",p3:"On the go: connect Telegram and message {name} from your phone. Dictation types what you say into any other app."},brain:{title:"The brain: an AI model you choose",say:"To think, {name} uses an AI model: from OpenAI, Google Gemini, Anthropic Claude, OpenRouter and others, or one running on your own computer. You choose which.",p1:"One key is enough. You add it in the next step and can switch models any time.",p2:"For agents, a subscription you already pay for (Claude or ChatGPT) avoids paying per call.",p3:"If one provider fails, {name} moves on to another one you connected instead of stopping."},tools:{title:"Tools: its hands",say:"Small jobs {name} does itself, right away, while you talk. That is what tools are: its hands on your computer and in your apps.",p1:"Your computer: open apps and websites, click and type on screen, look at your screen, read and write files, run commands.",p2:"Your apps and services: email, calendar, smart home and more, connected as Plugins or MCP from the Marketplace.",p3:"Skills: teach it a routine once and it can repeat it whenever you ask."},agents:{title:"Agents: a team for the big jobs",say:"When a job takes longer, like research, a report, a website or code, {name} hands it to an agent. You keep talking; the agent works in the background.",p1:"Agents live in the Agents area. Watch them work, chat with one, or give one a job directly.",p2:"A reviewer checks the agent's work before the result reaches you.",p3:"Coding agents such as Claude Code and Codex run side by side in the Agentic IDE, on your own projects. Agents can also run routines on a schedule."},memory:{title:"Memory: it gets to know you",say:"{name} remembers what matters: what you told it, what you like, the people and projects in your life.",p1:"The Wiki holds notes {name} can read, write and quote. You can open and edit every page.",p2:"Your profile collects what it knows about you, so you never have to repeat yourself.",p3:"Chats, notes and files are stored on your computer. Only what a model needs for an answer goes to the provider you chose."},safety:{title:"You stay in control",say:"Before {name} does anything, a safety check looks at it. Harmless things simply happen. Anything with real consequences waits for your yes.",p1:"Four levels: safe (runs), watched (runs and is logged), ask (waits for your OK), blocked (never runs).",p2:"Sending an email, deleting files or placing a call asks you first, and shows you exactly what will happen.",p3:"Keys stay in your system's keychain. Never say or type a key in the chat: {name} does not accept one there."},journey:{title:"Try it: follow one request",say:"Pick a request below and watch where it travels through {name}."},app:{title:"Where you find it in the app",say:"Everything you just saw has its own place in the sidebar on the left. Now let's set up the brain together; it takes about two minutes."}},journeys:{e1:{label:"What's on my calendar tomorrow?",s1:"You ask by voice.",s2:"Hears you and understands what you want.",s3:"Decides: this needs your calendar.",s4:"Reads your calendar through the connected app, a quick tool call.",s5:"The answer is spoken aloud within seconds."},e2:{label:"Build a website for my bakery",s1:"You ask in the chat.",s2:"Sees a big job.",s3:"Plans the work and picks the right helper.",s4:"An agent builds the page in the background while you keep talking; a reviewer checks it.",s5:"The finished page appears in Artifacts and in your chat."},e3:{label:"Remember: Anna's birthday is May 3",s1:"You mention it in passing.",s2:"Notices this is worth keeping.",s3:"Writes it to the Wiki, on Anna's page.",s4:"Next time you ask about Anna, {name} knows."},e4:{label:"Email the team that I'm running late",s1:"You say it while heading out.",s2:"Understands: an email to your team.",s3:"Writes the email.",s4:"Sending is a real action, so {name} shows you the email and waits for your yes.",s5:"Only after your OK it sends through your connected mail.",s6:"{name} confirms it is sent."}},app:{chats:"Chats",chats_sub:"Talk and type with {name}; every conversation is saved.",agents:"Agents",agents_sub:"Your team at work: create agents, give them jobs, watch them.",voice:"Voice",voice_sub:"Dictation into any app, your word list, spoken shortcuts.",artifacts:"Artifacts",artifacts_sub:"Pages, images and reports {name} made for you.",ide:"Agentic IDE",ide_sub:"Coding agents in real terminals, on your projects.",plugins:"Plugins",plugins_sub:"Connect apps and add skills; more in the Marketplace.",settings:"Settings",settings_sub:"API keys, memory, costs and your profile."}},keys:{title:"Add one API key",lede:"Your assistant needs one AI key to think and talk; without it, chat and voice stay off. This is the API Keys page: paste one key into a provider card and save it. OpenAI or Gemini gives you live voice with a single key.",waiting:"Waiting for a key…",connecting:"Switching everything on…",connected:"Connected: {provider}.",present:"A key is saved. You can continue.",partial:"Some parts did not switch ({parts}). You can fix them later on this page.",security:"Keys go into your system's keychain and only ever to the provider you picked.",later:"I'll add a key later"},subscriptions:{title:"Connect a subscription for your agents",lede:"This is the Agents tab. Sign in with a subscription you already pay for. We recommend Claude (Pro or Max) or ChatGPT (Codex). Click Connect on its row; your browser opens once.",waiting:"No subscription connected yet…",connected:"Connected: {names}.",why:"A subscription is a flat monthly price, so your agents' bigger jobs do not bill your API key per call.",later:"I'll connect one later"},permissions:{title:"Allow access on this Mac",lede:"These are the Mac permissions. Allow the ones you want; each row updates by itself.",note:"You can come back to them anytime in Settings. The restart at the end applies them."},voice:{title:"Choose your wake word",lede:`Type your word after "Hey" here and save it. The word also becomes the assistant's name. No wake word? The Call shortcut works anytime.`,on:'"{phrase}" is on. Say it anytime.',off:"No wake word yet. The Call shortcut works meanwhile.",later:"Skip, I'll use the Call shortcut"},ready:{title:"All set",lede:"Here is what is set up. Next, a short tour shows you around the app.",row_brain:"Brain",row_agents:"Agents",row_voice:"Activation",no_subscription:"No subscription",no_key:"No key yet",shortcut:"Call shortcut",autostart:"Start at login",no_key_note:"Without a key, chat and voice stay off until you add one on the API Keys page.",preview_note:"This is a replay, so nothing restarts.",restart_note:"When the tour ends, the app restarts once (about ten seconds) to switch everything on.",start:"Show me around"}},t={label:"App tour",next:"Next",finish:"Finish",skip:"Skip tour",step_of:"{current} of {total}",replay_title:"Setup and app tour",replay_body:"Explains again how {name} works, walks you through setup (API keys, agent subscriptions, wake word), then the short tour of the app. Nothing restarts.",replay:"Replay",steps:{voice:"This is how you talk to {name}. Click the bar, say your wake word or press your Call keys, then just speak. The wave shows who is talking.",new_chat:"Rather type? Start a new chat here, as text or voice. Every conversation lands under Recent chats.",agents:"Agents are your team: helpers that take on bigger jobs in the background. Let's look inside.",agents_world:"This is the Verse, your agents at work. Click one to chat with it or hand it a job. Next brings you back.",voice_hub:"Voice holds dictation into any app, your own word list and spoken shortcuts.",artifacts:"Everything {name} makes, from pages to images to reports, is kept in Artifacts.",ide:"The Agentic IDE runs coding agents side by side in real terminals, on your own projects.",plugins:"Plugins, skills and MCP connect {name} to your apps. The store icon at the bottom opens the Marketplace.",settings:"Settings, API keys, costs and your profile live here. You can replay this tour anytime from Settings → App.",done:"That's the tour. You're ready: talk to {name} whenever you like."}},o={title:"First steps",progress:"{done}/{total}",collapse:"Minimise",close:"Close",quest_of:"Step {current} of {total}",how_label:"How it works:",waiting:"Sent. Watch the chat: {name} is on it.",next:"Next step",finish:"Finish",skip:"Skip this one",try:{send:"Send it for me",voice:"Open voice mode",open:"Take me there"},show:{memory:"Open Notes",artifact:"Open Artifacts",agent:"Watch in Agents"},replay_title:"First steps with {name}",replay:"Start",replay_body:"Ten small, real things to try with {name}: talk, use tools, remember, build, hand off to agents. Each one is explained after it happened.",finished:{title:"You've got the basics!",body:"You completed {done} of {total} first steps. From now on, just talk to {name}: it decides whether to answer, use a tool or bring in an agent.",close:"Close"},quests:{wake:{title:"Wake {name} up",ask:'Say your wake word out loud, for example "Hey {name}". Or open voice mode and press the round button in the chat bar. Then just ask anything.',explain:"{name} is listening. That's all it takes: wake it up and talk like you would to a person.",how:"Your wake word is recognised right here on your computer. Only after it does your speech go to the brain, and the answer comes back as a voice."},ask:{title:"Ask your first question",ask:"Type or say a question. Try this one:",prompt:"What can you do for me? Give me three examples from my everyday life.",explain:"That was the simplest path: your words went to the brain, and it answered directly.",how:"The brain is the AI model you connected. Plain questions need no tools, so the answer comes in seconds. Every chat is saved under Recent chats."},tool:{title:"Let it use a tool",ask:"Now ask for something that needs its hands, not just its head:",prompt:"Open wikipedia.org in my browser.",explain:"This time the brain did not just answer: it used a tool to act on your computer.",how:"Tools are {name}'s hands. The brain picks one, the safety check approves it, and it runs. Under each reply you can open the steps and see every tool it used."},screen:{title:"Let it look at your screen",ask:"{name} can see your screen, but only when you ask. Try:",prompt:"What's on my screen right now? Describe it briefly.",explain:"{name} took one look at your screen and described it.",how:"A screen look is a single snapshot, taken only when a request needs it. It goes to the brain like a photo. Nothing records your screen in the background."},memory:{title:"Teach it something",ask:"Tell {name} something worth keeping:",prompt:"Remember that my favourite colour is blue and that I prefer short answers.",explain:"{name} saved this to its memory and will use it from now on.",how:"Facts land in your Wiki and profile, stored on your computer. Before answering, {name} looks up what it knows about you. You can read and edit every note in Notes."},artifact:{title:"Have it make something",ask:'{name} can build finished things: pages, overviews, small tools. Say "artifact" to ask for one:',prompt:"Create an artifact: a one-page overview of the planets in our solar system, with one fun fact each.",explain:"{name} started building the page. When it is ready, it appears in Artifacts.",how:"An artifact is a bigger piece of work, so {name} hands it to a worker on a strong model. It builds one self-contained page, and Artifacts keeps it for you to open again later."},agent:{title:"Hand a big job to an agent",ask:"For longer work, {name} brings in an agent. You can keep talking while it works:",prompt:"Research the three best budget laptops right now and write me a short comparison.",explain:"{name} handed the job to an agent. It works in the background; the result comes back to your chat.",how:"{name} stays your single contact. It plans the job and starts an agent, and a reviewer checks the result before it reaches you. You can watch the progress in Agents."},team:{title:"Meet your team",ask:"Agents are helpers with their own role. Open the Agents area to meet them.",explain:"This is where your agents live and work.",how:"Create your own agent with its own role, model and instructions, for example a researcher or a writer. Click an agent to chat with it or give it a job. {name} can also hand work to it for you."},plugin:{title:"Connect an app",ask:"Plugins connect {name} to the apps you use: email, calendar, notes, smart home and more.",explain:"Here you connect your apps. Pick one you use every day and click Connect; your browser opens once to sign in.",how:`Each connected app becomes a new tool for {name}. Afterwards just ask, for example "What's on my calendar tomorrow?". Anything that sends or changes something still asks you first.`},ide:{title:"Let agents write code",ask:"The Agentic IDE runs coding agents such as Claude Code and Codex in real terminals, on your own projects.",explain:"This is the Agentic IDE. Open a project folder and start a coding agent in a pane.",how:"Each pane is a real terminal with its own agent. Talk to them by typing, or by voice through {name}. Several can work side by side on the same project."}}},a={first_run:e,app_tour:t,first_steps:o};export{t as app_tour,a as default,e as first_run,o as first_steps};
